const express = require('express');
const crypto = require('crypto');
const { URL } = require('url');

const app = express();

// Fail closed: require a strong secret to be configured, never use a hardcoded default
const STATE_SECRET = process.env.STATE_SECRET;
if (!STATE_SECRET || STATE_SECRET.length < 32) {
  throw new Error('STATE_SECRET environment variable must be set to a strong (>=32 char) secret');
}

// Multi-tenant database connection pool
const tenantConnections = new Map();
const oauthStates = new Map();
const ALLOWED_REDIRECT_ORIGINS = ['https://app.example.com', 'https://dashboard.example.com'];

class TenantIsolationLayer {
  constructor(tenantId) {
    this.tenantId = tenantId;
    this.schema = `tenant_${tenantId.replace(/[^a-z0-9]/gi, '')}`;
  }

  async query(sql, params) {
    const conn = tenantConnections.get(this.tenantId);
    if (!conn) throw new Error('No connection for tenant');
    return conn.query(`SET search_path TO ${this.schema}; ${sql}`, params);
  }
}

function normalizeRedirectUri(uri) {
  try {
    const parsed = new URL(uri);
    // Normalize by removing default ports and trailing slashes
    let normalized = `${parsed.protocol}//${parsed.hostname}`;
    if (parsed.port && parsed.port !== '443' && parsed.port !== '80') {
      normalized += `:${parsed.port}`;
    }
    normalized += parsed.pathname.replace(/\/+$/, '');
    if (parsed.search) normalized += parsed.search;
    return normalized;
  } catch (e) {
    return null;
  }
}

function validateRedirectOrigin(redirectUri) {
  const normalized = normalizeRedirectUri(redirectUri);
  if (!normalized) return false;

  const parsedRedirect = new URL(normalized);
  const redirectOrigin = `${parsedRedirect.protocol}//${parsedRedirect.hostname}`;

  return ALLOWED_REDIRECT_ORIGINS.some(allowed => {
    const parsedAllowed = new URL(allowed);
    const allowedOrigin = `${parsedAllowed.protocol}//${parsedAllowed.hostname}`;
    return redirectOrigin === allowedOrigin;
  });
}

function generateStateToken(tenantId, redirectUri) {
  const stateId = crypto.randomBytes(16).toString('hex');
  const hmac = crypto.createHmac('sha256', STATE_SECRET);
  hmac.update(`${stateId}:${tenantId}`);
  const signature = hmac.digest('hex');

  oauthStates.set(stateId, {
    tenantId,
    redirectUri,
    createdAt: Date.now(),
    signature
  });

  return `${stateId}.${signature}`;
}

function verifyStateToken(stateParam) {
  const parts = stateParam.split('.');
  if (parts.length !== 2) return null;

  const [stateId, providedSig] = parts;
  const stored = oauthStates.get(stateId);
  if (!stored) return null;

  // Timing-safe comparison for signature
  const sigBuffer = Buffer.from(providedSig, 'hex');
  const storedBuffer = Buffer.from(stored.signature, 'hex');

  if (sigBuffer.length !== storedBuffer.length) return null;
  if (!crypto.timingSafeEqual(sigBuffer, storedBuffer)) return null;

  // Check expiry (5 minutes)
  if (Date.now() - stored.createdAt > 300000) {
    oauthStates.delete(stateId);
    return null;
  }

  oauthStates.delete(stateId);
  return stored;
}

app.get('/oauth/authorize', (req, res) => {
  const { tenant_id, redirect_uri } = req.query;

  if (!tenant_id || !redirect_uri) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  if (!validateRedirectOrigin(redirect_uri)) {
    return res.status(403).json({ error: 'Invalid redirect origin' });
  }

  const state = generateStateToken(tenant_id, redirect_uri);
  const authUrl = `https://idp.example.com/authorize?client_id=app&state=${state}&redirect_uri=${encodeURIComponent(redirect_uri)}`;

  res.redirect(authUrl);
});

app.get('/oauth/callback', async (req, res) => {
  const { code, state, error } = req.query;

  if (error) {
    return res.status(400).json({ error: 'OAuth error', detail: error });
  }

  if (!code || !state) {
    return res.status(400).json({ error: 'Missing code or state' });
  }

  const stateData = verifyStateToken(state);
  if (!stateData) {
    return res.status(403).json({ error: 'Invalid or expired state' });
  }

  // Always use the redirect_uri bound to the verified state token
  // Never trust redirect_uri from the callback query parameters
  const finalRedirect = stateData.redirectUri;

  const tenant = new TenantIsolationLayer(stateData.tenantId);

  try {
    // Exchange code for token (simulated)
    const tokenData = { access_token: crypto.randomBytes(32).toString('hex'), tenant_id: stateData.tenantId };

    // Store session in tenant-isolated storage
    await tenant.query('INSERT INTO sessions (token, created_at) VALUES ($1, NOW())', [tokenData.access_token]);

    // Redirect with token
    const redirectUrl = new URL(finalRedirect);
    redirectUrl.searchParams.set('token', tokenData.access_token);
    redirectUrl.searchParams.set('tenant', stateData.tenantId);

    res.redirect(redirectUrl.toString());
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000, () => console.log('OAuth service running on :3000'));

module.exports = app;
